                check_dir=check_dir,
            )
        )

    def with_prefix(self, prefix: str) -> "_FrontendRouteGroup":
        route_group = copy.copy(self)
        route_group.routes = [
            route.with_path(_join_frontend_paths(prefix, route.path))
            for route in self.routes
        ]
